const body = $json.body ?? $json;
if (!body.conversationId || !body.messageId || !body.adminUserId || !body.message) {
  throw new Error('conversationId, messageId, adminUserId and message are required');
}
const message = String(body.message);
const lower = message.toLowerCase();
const uuidMatch = message.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
let toolName = 'dashboard_summary';
let input = { page: 0, size: 5 };
if (lower.includes('report')) {
  toolName = uuidMatch ? 'get_report_detail' : 'search_reports';
  input = uuidMatch ? { reportId: uuidMatch[0] } : { page: 0, size: 5 };
} else if (lower.includes('moderation')) {
  toolName = 'get_moderation_queue_summary';
} else if (lower.includes('user')) {
  toolName = uuidMatch ? 'get_user_summary' : 'search_users';
  input = uuidMatch ? { userId: uuidMatch[0] } : { search: message.slice(0, 80), page: 0, size: 5 };
} else if (lower.includes('blog')) {
  toolName = uuidMatch ? 'get_blog_summary' : 'search_blogs';
  input = uuidMatch ? { blogId: uuidMatch[0] } : { page: 0, size: 5 };
} else if (lower.includes('comment')) {
  toolName = uuidMatch ? 'get_comment_summary' : 'search_comments';
  input = uuidMatch ? { commentId: uuidMatch[0] } : { page: 0, size: 5 };
} else if (lower.includes('cafe') || lower.includes('page')) {
  toolName = uuidMatch ? 'get_cafe_page_summary' : 'search_cafe_pages';
  input = uuidMatch ? { pageId: uuidMatch[0] } : { page: 0, size: 5 };
}
const toolApi = body.toolApi ?? {};
const baseUrl = toolApi.baseUrl || $env.ADMIN_ASSISTANT_TOOL_BASE_URL || 'http://host.docker.internal:8080/api/admin/assistant/tools';
return [{
  json: {
    request: body,
    toolName,
    toolUrl: `${baseUrl.replace(/\/$/, '')}/${toolName}`,
    toolToken: toolApi.token || $env.ADMIN_ASSISTANT_TOOL_TOKEN,
    toolPayload: {
      conversationId: body.conversationId,
      messageId: body.messageId,
      adminUserId: body.adminUserId,
      input
    }
  }
}];

const selected = $('Select BE Tool').first().json;
const request = selected.request;
const toolResponse = $json.data ?? $json;
const sourceRefSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    type: { type: ['string', 'null'] },
    toolName: { type: ['string', 'null'] },
    id: { type: ['string', 'null'] }
  },
  required: ['type', 'toolName', 'id']
};
const draftPayloadSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    reportId: { type: ['string', 'null'] },
    blogId: { type: ['string', 'null'] },
    commentId: { type: ['string', 'null'] },
    userId: { type: ['string', 'null'] },
    pageId: { type: ['string', 'null'] },
    jobId: { type: ['string', 'null'] }
  },
  required: ['reportId', 'blogId', 'commentId', 'userId', 'pageId', 'jobId']
};
const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    answer: { type: 'string' },
    citations: { type: 'array', items: sourceRefSchema },
    draftAction: {
      anyOf: [
        { type: 'null' },
        {
          type: 'object',
          additionalProperties: false,
          properties: {
            actionType: { type: 'string', enum: ['REPORT_RESOLVE', 'REPORT_REJECT', 'REPORT_ASK_AI_RESOLUTION', 'REPORT_CANCEL_AUTO_APPLY', 'BLOG_HIDE', 'BLOG_REMOVE', 'COMMENT_HIDE', 'COMMENT_REMOVE', 'USER_DEACTIVATE', 'CAFE_PAGE_SUSPEND'] },
            payload: draftPayloadSchema,
            explanation: { type: 'string' },
            sourceRefs: { type: 'array', items: sourceRefSchema }
          },
          required: ['actionType', 'payload', 'explanation', 'sourceRefs']
        }
      ]
    }
  },
  required: ['answer', 'citations', 'draftAction']
};
const policy = [
  'You are CafeStory Admin Assistant. You help admins inspect core operations: dashboard, reports, moderation, users, blogs, comments, and cafe pages.',
  'Use the provided BE tool result as the source of truth. Do not claim facts that are not in toolResult or supplied policy/docs context.',
  'Masking is intentional. Never ask for passwords, tokens, secrets, or raw payment data.',
  'You may propose a draftAction only when the user clearly asks to perform an admin action and a specific target id is available in the user message or tool result.',
  'Draft actions are proposals only; backend will require admin confirmation before execution.',
  'Do not include payments/payout action suggestions in V1.'
].join('\n');
const docs = [
  { id: 'reports-v2', keywords: ['report', 'moderation', 'ai', 'resolve'], text: 'Reports are resolved separately from moderation results. Ask AI recommendations do not mutate report/content unless a confirmed draft action is executed.' },
  { id: 'admin-actions', keywords: ['hide', 'remove', 'suspend', 'reject', 'execute'], text: 'All assistant actions must be draft actions first. Backend validates target id, whitelist, admin authority, and expiration before execution.' },
  { id: 'privacy', keywords: ['user', 'email', 'phone', 'secret', 'token'], text: 'Admin assistant responses must respect masking. Do not reveal raw emails, phone numbers, passwords, tokens, secrets, payment or payout details in V1.' },
  { id: 'feed-ranking', keywords: ['feed', 'ranking', 'blog'], text: 'Feed ordering and ranking should be explained as system behavior only when supported by retrieved project docs or tool data; do not invent ranking weights.' },
  { id: 'core-ops-scope', keywords: ['dashboard', 'comment', 'cafe', 'page', 'blog'], text: 'V1 scope covers dashboard, reports, moderation, users, blogs, comments, and cafe pages. Payments and payouts are excluded from assistant action suggestions.' }
];
const messageLower = String(request.message || '').toLowerCase();
const docsContext = docs.filter((doc) => doc.keywords.some((keyword) => messageLower.includes(keyword) || selected.toolName.includes(keyword))).slice(0, 3);
if (!docsContext.length) docsContext.push(docs.find((doc) => doc.id === 'core-ops-scope'));
return [{
  json: {
    selectedTool: selected.toolName,
    toolResponse,
    docsContext,
    openaiRequest: {
      model: request.model || $env.OPENAI_ASSISTANT_MODEL || 'gpt-4o-mini',
      input: [
        { role: 'system', content: [{ type: 'input_text', text: policy }] },
        { role: 'user', content: [{ type: 'input_text', text: JSON.stringify({ message: request.message, pageContext: request.pageContext ?? {}, history: request.history ?? [], selectedTool: selected.toolName, docsContext, toolResult: toolResponse }, null, 2) }] }
      ],
      text: { format: { type: 'json_schema', name: 'cafestory_admin_assistant_response', strict: true, schema } }
    }
  }
}];

const selectedTool = $('Build OpenAI Assistant Request').first().json.selectedTool;
const toolResponse = $('Build OpenAI Assistant Request').first().json.toolResponse;
function outputText(response) {
  if (typeof response.output_text === 'string') return response.output_text;
  const output = Array.isArray(response.output) ? response.output : [];
  for (const item of output) {
    const content = Array.isArray(item.content) ? item.content : [];
    for (const part of content) {
      if (typeof part.text === 'string') return part.text;
    }
  }
  return '';
}
const text = outputText($json).trim();
const parsed = text ? JSON.parse(text) : { answer: 'No assistant response was generated.', citations: [], draftAction: null };
if (parsed.draftAction && parsed.draftAction.payload) {
  parsed.draftAction.payload = Object.fromEntries(Object.entries(parsed.draftAction.payload).filter(([, value]) => value !== null && value !== undefined && value !== ''));
}
const citations = Array.isArray(parsed.citations) ? parsed.citations : [];
if (!citations.length) {
  citations.push({ type: 'tool', toolName: selectedTool });
}
return [{
  json: {
    answer: String(parsed.answer || 'No assistant response was generated.'),
    modelName: $json.model || $env.OPENAI_ASSISTANT_MODEL || 'gpt-4o-mini',
    citations,
    toolCalls: [{ toolName: selectedTool, maskedFields: toolResponse.maskedFields || [], sourceRefs: toolResponse.sourceRefs || [] }],
    draftAction: parsed.draftAction || null
  }
}];
